"""Create empty PostgreSQL schema without sample data."""
import os
from psycopg import connect
url=os.environ.get('DATABASE_URL')
if not url: raise SystemExit('Set DATABASE_URL first')
with connect(url) as c:
    c.execute("CREATE TABLE IF NOT EXISTS users(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user')")
    c.execute("CREATE TABLE IF NOT EXISTS products(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,price DOUBLE PRECISION NOT NULL CHECK(price>=0),stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),image TEXT DEFAULT '',active INTEGER NOT NULL DEFAULT 1)")
    c.execute("CREATE TABLE IF NOT EXISTS tasks(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,reward TEXT NOT NULL DEFAULT 'Nessun compenso',active INTEGER NOT NULL DEFAULT 1)")
    c.execute("CREATE TABLE IF NOT EXISTS submissions(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),task_id INTEGER NOT NULL REFERENCES tasks(id),note TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL)")
    c.execute("CREATE TABLE IF NOT EXISTS orders(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),product_id INTEGER NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL,unit_price DOUBLE PRECISION NOT NULL,status TEXT NOT NULL DEFAULT 'requested',created_at TEXT NOT NULL)")
print('Empty schema created.')
